__NUXT_JSONP__("/desarrollo-sostenible/noticias/amlo_recorto_y_cambio_programas_del_campo_pero_no_quito_todos_los_apoyos", (function(a,b,c,d,e,f,g,h,i,j,k,l,m,n,o,p,q,r,s,t,u,v,w,x){return {data:[{post:{slug:"amlo_recorto_y_cambio_programas_del_campo_pero_no_quito_todos_los_apoyos",title:"AMLO recortó y cambió programas del campo, pero no quitó “todos los apoyos”",date:"2024-04-20T19:24:11.739Z",img:"https:\u002F\u002Fucarecdn.com\u002Fd696b572-2a69-46b1-8aea-1cae91dc9740\u002F","img-alt":"Sembrando Vida",autor:"El Sabueso, Animal Político",link:"https:\u002F\u002Fanimalpolitico.com\u002Fverificacion-de-hechos\u002Ffact-checking\u002Famlo-recorte-apoyos-campo",category:"desarrollo-sostenible",extracto:"Laure Delalande, directora de Inclusión y Desarrollo Sostenible en Ethos, dijo: “Anteriormente existían más programas que beneficiaban a productores grandes, en particular todos los programas relacionados con los precios de garantía… había programas que sobraban”.",toc:[{id:r,depth:g,text:s},{id:t,depth:g,text:u},{id:v,depth:g,text:w}],body:{type:"root",children:[{type:b,tag:d,props:{},children:[{type:a,value:"Xóchitl Gálvez, candidata a la presidencia de México por el PRI, PAN y PRD, aseguró que el gobierno morenista abandonó al campo y que ya “no hay programas” para atenderlo. Y en la misma línea se pronunciaron Pablo Lemus, candidato de MC para la gubernatura de Jalisco y Miguel Ángel Yunes, candidato al Senado por el PRI-PAN-PRD, al decir que quitaron “todos los apoyos” al sector."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Y es verdad que disminuyó el presupuesto para la Secretaría de Agricultura y Desarrollo Rural (Sader), sin embargo, el gobierno sigue asignando recursos para el campo, no eliminó todos los apoyos de gobiernos anteriores y creó el "},{type:b,tag:e,props:{href:"https:\u002F\u002Fprogramasparaelbienestar.gob.mx\u002Faumenta-apoyo-del-programa-sembrando-vida-beneficiarios-recibiran-6-mil-250-pesos-mensuales\u002F#:~:text=250%20pesos%20mensuales-,Aumenta%20apoyo%20del%20programa%20Sembrando%20Vida%2C%20beneficiarios,6%20mil%20250%20pesos%20mensuales&text=A%20partir%20de%20enero%20de,6%20mil%20250%20pesos%20mensuales.",rel:[h,i,j],target:k},children:[{type:a,value:"programa Sembrando Vida"}]},{type:a,value:" –al que se le han detectado irregularidades– que consiste en entregar 6,250 pesos mensuales a pequeños productores."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"De acuerdo con especialistas consultadas por El Sabueso, en realidad hubo un cambio en el destino de los recursos: anteriormente beneficiaban a medianos y grandes productores, así como de financiamiento, y hoy se focaliza en la entrega de dinero y productos."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"El Sabueso contactó a los  equipos de prensa de Gálvez,  Lemus y Yunes para obtener un comentario al respecto, pero no enviaron respuesta."}]},{type:a,value:c},{type:b,tag:l,props:{id:r},children:[{type:b,tag:e,props:{href:"#cambio-en-programas-del-campo",ariaHidden:m,tabIndex:n},children:[{type:b,tag:o,props:{className:[p,q]},children:[]}]},{type:b,tag:f,props:{},children:[{type:a,value:s}]}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"De acuerdo con el Grupo Consultor de Mercados Agrícolas (GCMA), de 2019 a la fecha se eliminaron 23 de los componentes de los programas del campo, en tanto que 22 siguen vigentes y otros tres se crearon en este sexenio."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"El reporte de GCMA destaca la eliminación del Programa de Financiamiento y Aseguramiento al Medio Rural y la disminución de los recursos para el Programa de Fomento a la Inversión y Productividad, en tanto que se beneficia a “programas asistenciales”."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Andrés Manuel López Obrador ha planteado que su estrategia está centrada en los pequeños productores, con el objetivo de alcanzar la llamada autosuficiencia alimentaria, lo cual no ha sucedido hasta el momento."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Esto llevó a una reestructuración de los programas para el campo, que dejó en segundo plano a empresarios que antes recibían recursos, coincidieron especialistas. "}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"“Este gobierno ha transformado completamente la estructura de los subsidios, en los gobiernos anteriores los subsidios agrícolas iban principalmente a los grandes productores”, dijo Helena Cotler, investigadora del Centro de Investigación en Ciencias de Información Geoespacial, en entrevista con El Sabueso."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"La distribución de los programas, señaló, “era dramáticamente diferencial. En los que tenían zonas de muy alta marginación se invertían 5,483 pesos, en municipios indígenas 5,778, y en los municipios de baja marginación se daban 43 mil pesos de promedio por persona”."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Laure Delalande, directora de Inclusión y Desarrollo Sostenible en la organización Ethos, coincidió: “Anteriormente existían más programas que beneficiaban a productores grandes, en particular todos los programas relacionados con los precios de garantía… había programas que sobraban”."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Uberto Salgado, investigador del Instituto de Investigaciones Económicas de la UNAM, señaló que los apoyos hoy eliminados fueron creados con la idea de compensar a productores afectados por la competencia internacional, pero terminaron beneficiando a quienes tenían mayores cantidades de tierra."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Actualmente, el gobierno destaca cuatro programas para el campo: Fertilizantes para el Bienestar; Producción para el Bienestar; Sembrando Vida y Precios de Garantía."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Para Juan Carlos Anaya, director de GCMA,  “se requiere volver a programas de bienes públicos y apoyos focalizados y diferenciados, que promuevan la productividad, aumentar la producción y rentabilidad de los productores , pecuarios y pescadores”."}]},{type:a,value:c},{type:b,tag:l,props:{id:t},children:[{type:b,tag:e,props:{href:"#recursos-de-sader-disminuyeron-pero-gasto-del-campo-se-mantiene",ariaHidden:m,tabIndex:n},children:[{type:b,tag:o,props:{className:[p,q]},children:[]}]},{type:b,tag:f,props:{},children:[{type:a,value:u}]}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Datos de la Cuenta Pública muestran que, por sí sola, la Sader tuvo una disminución en cuanto a sus recursos ejercidos, a comparación de otras administraciones. "},{type:b,tag:f,props:{},children:[{type:a,value:"En 2015 ejerció 136 mil millones de pesos"}]},{type:a,value:" (equivalentes a pesos de 2024) y en 2022 gastó menos de la mitad, 62 mil millones."}]},{type:a,value:c},{type:b,tag:l,props:{id:v},children:[{type:b,tag:e,props:{href:"#sembrando-vida-proyecto-insignia-para-el-campo-pero-con-irregularidades",ariaHidden:m,tabIndex:n},children:[{type:b,tag:o,props:{className:[p,q]},children:[]}]},{type:b,tag:f,props:{},children:[{type:a,value:w}]}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Sembrando Vida, el programa insignia del gobierno federal para el campo, con atención a la pobreza rural, ha presentado varias irregularidades."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Apenas en febrero, "},{type:b,tag:e,props:{href:"https:\u002F\u002Finforme.asf.gob.mx\u002FDocumentos\u002FAuditorias\u002F2022_0255_a.pdf",rel:[h,i,j],target:k},children:[{type:a,value:"la Auditoría Superior de la Federación (ASF) indicó"}]},{type:a,value:" que de 2,607 expedientes de beneficiarios del programa, 694 no contaban con evidencia para ser elegidos con este apoyo."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"También informó que se autorizaron recursos económicos adicionales, pero no se estableció el mecanismo mediante el cual se debían adquirir los bienes ni tampoco se dio seguimiento para verificar que el apoyo se aplicara correctamente. "}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Además, en otro "},{type:b,tag:e,props:{href:"https:\u002F\u002Finforme.asf.gob.mx\u002FDocumentos\u002FAuditorias\u002F2022_0256_a.pdf",rel:[h,i,j],target:k},children:[{type:a,value:"informe"}]},{type:a,value:", la ASF señaló que el programa no tenía la documentación completa de los procedimientos de las adquisiciones de plantas y servicio de transporte de 2022. Y en otros casos, donde sí había documentos, estos no cumplían con la normatividad."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"La auditoría también afirmó que no se identificaron las personas que recibieron el apoyo en especie, ya que la Secretaría del Bienestar no contaba con el registro y únicamente los tienen identificados por comunidad de apoyo campesino."}]}]},dir:"\u002Fnoticias",path:"\u002Fnoticias\u002Famlo_recorto_y_cambio_programas_del_campo_pero_no_quito_todos_los_apoyos",extension:".md",createdAt:x,updatedAt:x}}],fetch:{},mutations:[]}}("text","element","\n","p","a","strong",3,"nofollow","noopener","noreferrer","_blank","h3","true",-1,"span","icon","icon-link","cambio-en-programas-del-campo","Cambio en programas del campo","recursos-de-sader-disminuyeron-pero-gasto-del-campo-se-mantiene","Recursos de Sader disminuyeron, pero gasto del campo se mantiene","sembrando-vida-proyecto-insignia-para-el-campo-pero-con-irregularidades","Sembrando Vida, proyecto insignia para el campo, pero con irregularidades","2024-10-02T22:32:44.083Z")));